'use strict';

/**
 * Load the labelled silence profile and format the prompt block used for ordinary
 * unaddressed chat. The profile is generated by `npm run corpus:learn` from
 * `fixtures/p1/chat-corpus.csv`; runtime never parses GBK CSV and never calls a model here.
 */

const fs = require('node:fs');
const path = require('node:path');

const DEFAULT_PROFILE = path.join(__dirname, '..', '..', 'config', 'chat-silence-profile.json');

function loadChatSilenceProfile(file = DEFAULT_PROFILE) {
  const target = path.resolve(file);
  try {
    const profile = JSON.parse(fs.readFileSync(target, 'utf8'));
    if (!profile || profile.version !== 1 || !Array.isArray(profile.examples)) return null;
    return profile;
  } catch {
    return null;
  }
}

function formatSilencePolicy(profile, options = {}) {
  if (!profile || !Array.isArray(profile.examples) || !profile.examples.length) return null;
  const limit = Math.max(1, Number(options.limit) || profile.examples.length);
  const examples = profile.examples.slice(0, limit);
  const silent = examples.filter((row) => row.label === 'silent').length;
  const participate = examples.filter((row) => row.label === 'participate').length;
  const counts = profile.counts || {};
  const lines = [
    'ORDINARY CHAT POLICY (learned from real labelled server chat):',
    `- Corpus labels: silent=${counts.silent || '?'}, participate=${counts.participate || '?'}.`,
    `- Injected examples: ${silent} SILENT + ${participate} PARTICIPATE.`,
    `- ${profile.policy || 'Default to silence on background chat; participate only when directly relevant.'}`,
    '- This is UNADDRESSED background chat. Use the policy and examples above; the speaker is not necessarily talking to you.',
    '- Speak when the policy says so: a direct question or mention, help/plan talk, continuing your conversation, a player achievement worth a short praise, frustration/loss worth a short comfort, confusion about a gameplay mechanic (you MUST call web_search once before answering, even if you think you know; if search fails, say you cannot confirm), or clear group banter where a brief reaction fits.',
    '- Stay silent on neutral statements, acknowledgements, bare reactions/fragments, and third-party dialogue that does not invite you.',
    '- When genuinely unsure, prefer {"tool":"silence"}; do not turn every background line into an interjection.',
    'Labelled examples (up to 4 preceding chat lines -> player line -> decision):',
    ...examples.map((row) => {
      const context = Array.isArray(row.context) ? row.context.slice(-4) : [];
      const lines = [];
      if (context.length) {
        lines.push('  - context:');
        for (const item of context) {
          const who =
            item.role === 'agent'
              ? 'self'
              : item.speaker && !/^AgentDeepSeek$/i.test(item.speaker)
                ? item.speaker
                : 'player';
          lines.push(`    - ${who}: ${String(item.text || '')}`);
        }
      }
      lines.push(`  - ${JSON.stringify(String(row.text || ''))} -> ${String(row.label).toUpperCase()}`);
      return lines.join('\n');
    })
  ];
  return lines.join('\n');
}

module.exports = { DEFAULT_PROFILE, loadChatSilenceProfile, formatSilencePolicy };
